// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Sign in
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out and end the session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe The signed-in user
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetAuthMethods How this server lets people sign in
	// (GET /auth/methods)
	GetAuthMethods(ctx context.Context, request GetAuthMethodsRequestObject) (GetAuthMethodsResponseObject, error)
	// OidcCallback Finish signing in through the OIDC provider
	// (GET /auth/oidc/callback)
	OidcCallback(ctx context.Context, request OidcCallbackRequestObject) (OidcCallbackResponseObject, error)
	// OidcLogin Start signing in through the OIDC provider
	// (GET /auth/oidc/login)
	OidcLogin(ctx context.Context, request OidcLoginRequestObject) (OidcLoginResponseObject, error)
	// Signup Create an account and sign in
	// (POST /auth/signup)
	Signup(ctx context.Context, request SignupRequestObject) (SignupResponseObject, error)
	// GetCatalogCover A game's cover art, fetched from IGDB by the server
	// (GET /catalog/covers/{coverId})
	GetCatalogCover(ctx context.Context, request GetCatalogCoverRequestObject) (GetCatalogCoverResponseObject, error)
	// ListCatalogGames Every game on a platform, from IGDB, marked when the library has it
	// (GET /catalog/games)
	ListCatalogGames(ctx context.Context, request ListCatalogGamesRequestObject) (ListCatalogGamesResponseObject, error)
	// GetCatalogGame One game's details from IGDB, for a platform in the library
	// (GET /catalog/games/{gameId})
	GetCatalogGame(ctx context.Context, request GetCatalogGameRequestObject) (GetCatalogGameResponseObject, error)
	// ListCatalogPlatforms The library's platforms, matched to the game catalog (IGDB)
	// (GET /catalog/platforms)
	ListCatalogPlatforms(ctx context.Context, request ListCatalogPlatformsRequestObject) (ListCatalogPlatformsResponseObject, error)
	// ListCatalogRequests The signed-in user's requests for catalog games on a platform
	// (GET /catalog/requests)
	ListCatalogRequests(ctx context.Context, request ListCatalogRequestsRequestObject) (ListCatalogRequestsResponseObject, error)
	// RequestCatalogGame Request a game from the catalog
	// (POST /catalog/requests)
	RequestCatalogGame(ctx context.Context, request RequestCatalogGameRequestObject) (RequestCatalogGameResponseObject, error)
	// GetCatalogScreenshot A game's screenshot, fetched from IGDB by the server
	// (GET /catalog/screenshots/{imageId})
	GetCatalogScreenshot(ctx context.Context, request GetCatalogScreenshotRequestObject) (GetCatalogScreenshotResponseObject, error)
	// ListPlatforms Platform folders in the ROM library
	// (GET /platforms)
	ListPlatforms(ctx context.Context, request ListPlatformsRequestObject) (ListPlatformsResponseObject, error)
	// ListRequests The signed-in user's requests, newest first
	// (GET /requests)
	ListRequests(ctx context.Context, request ListRequestsRequestObject) (ListRequestsResponseObject, error)
	// CreateRequest Request a release from a search, for a platform
	// (POST /requests)
	CreateRequest(ctx context.Context, request CreateRequestRequestObject) (CreateRequestResponseObject, error)
	// DeleteRequest Remove a request
	// (DELETE /requests/{requestId})
	DeleteRequest(ctx context.Context, request DeleteRequestRequestObject) (DeleteRequestResponseObject, error)
	// RetryRequest Try a failed request again
	// (POST /requests/{requestId}/retry)
	RetryRequest(ctx context.Context, request RetryRequestRequestObject) (RetryRequestResponseObject, error)
	// Search Search Prowlarr for torrent releases
	// (GET /search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// GetStatus Which integrations the server has configured
	// (GET /status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

